import { createHash } from "node:crypto";
import { db } from "./db";
import { verifyTOTP } from "./totp";
import { decryptSecret } from "./crypto-box";

/**
 * TOTP verification primitives — deliberately a PLAIN module, not `"use server"`.
 *
 * SECURITY (2026-07-25): `verifyTotpForUser` used to live in `lib/actions-2fa.ts`,
 * which carries `"use server"` at the top. Every export of such a module is a
 * registered, network-callable server action. That made this function a public
 * endpoint taking an arbitrary `userId`, performing no authentication, no
 * ownership check and no rate limiting, returning a raw boolean — and mutating
 * state, because a matching backup code is consumed. `login()` is throttled to 10
 * attempts per 15 minutes per email+IP; calling this action directly bypassed that
 * completely, allowing unlimited TOTP and backup-code guessing against a named
 * account. Victim user IDs were obtainable from the team page.
 *
 * Keeping these here means they can only ever be reached by server code that
 * imports them (the login flow, and the 2FA management actions) — there is no
 * action ID for a client to call. Do NOT re-export any of this from a
 * `"use server"` module.
 */

/** Hash a backup code for storage/comparison. Case- and whitespace-insensitive. */
export function hashCode(code: string): string {
  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
}

/**
 * Resolve a user's TOTP secret, preferring the encrypted column and falling back
 * to any legacy plaintext value so already-enrolled users keep working.
 */
export function totpSecretOf(user: {
  totpSecret: string | null;
  totpSecretEnc: string | null;
}): string | null {
  return decryptSecret(user.totpSecretEnc) ?? user.totpSecret;
}

/**
 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
 * valid one-time backup code (which is then removed).
 *
 * Callers MUST have already established that the request is entitled to attempt
 * a 2FA check for this user (i.e. the password stage passed) and MUST apply their
 * own rate limiting — this function deliberately has neither, which is precisely
 * why it must never be exposed as a server action.
 */
export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user || !user.totpEnabled) return false;
  const secret = totpSecretOf(user);
  if (!secret) return false;

  if (verifyTOTP(secret, code)) return true;

  // Fall back to consuming a backup code.
  const submitted = hashCode(code);
  const idx = user.backupCodes.indexOf(submitted);
  if (idx === -1) return false;
  const remaining = user.backupCodes.filter((_, i) => i !== idx);
  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
  return true;
}
